    return Math.random() * 100;
  }
  get bigint() {
    return BigInt(Math.floor(Math.random() * 10000));
  }
  get boolean() {
    return Math.random() < 0.5;
  }
  get date() {
    return new Date(Math.floor(Date.now() * Math.random()));
  }
  get symbol() {
    return testSymbol;
  }

